</style>

<!-- jQuery (required for date range picker and AJAX) -->
<script src="https://code.jquery.com/jquery-3.6.0.min.js"></script>

<!-- Moment.js (required for date range picker) -->
<script src="https://cdn.jsdelivr.net/npm/moment@2.29.4/moment.min.js"></script>

<!-- Date Range Picker CSS and JS -->
<link rel="stylesheet" type="text/css" href="https://cdn.jsdelivr.net/npm/daterangepicker/daterangepicker.css" />
<script type="text/javascript" src="https://cdn.jsdelivr.net/npm/daterangepicker/daterangepicker.min.js"></script>

<!-- Bootstrap 5 JS (for dropdown functionality) -->
<!-- <script src="https://cdn.jsdelivr.net/npm/bootstrap@5.3.0/dist/js/bootstrap.bundle.min.js"></script> -->
<script>
    // Guest Dropdown Functions - Define them globally first

    
    // Main Guest Selector - Uses the same modal pattern as attraction booking
    window.openMainGuestSelector = function() {
        console.log('openMainGuestSelector called');
        
        // Get current values from hidden inputs
        const male = parseInt(document.getElementById('male').value) || 0;
        const female = parseInt(document.getElementById('female').value) || 0;
        const children = parseInt(document.getElementById('children').value) || 0;
        const infants = parseInt(document.getElementById('infants').value) || 0;
        const adults = male + female;
        
        console.log('Current guest values:', {adults, male, female, children, infants});
        
        // Create modal if it doesn't exist
        if (!document.getElementById('mainGuestSelectorModal')) {
            createMainGuestSelectorModal();
        }
        
        // Set modal values
        document.getElementById('mainModalMale').textContent = male;
        document.getElementById('mainModalFemale').textContent = female;
        document.getElementById('mainModalChildren').textContent = children;
        document.getElementById('mainModalInfants').textContent = infants;
        
        // Update child age dropdowns (will auto-populate existing ages)
        updateChildAgeDropdowns(children);
        
        // Show modal
        const modal = document.getElementById('mainGuestSelectorModal');
        const modalInstance = new bootstrap.Modal(modal);
        
        // Add event listeners to handle focus properly
        modal.addEventListener('hidden.bs.modal', function () {
            // Remove focus from any focused elements when modal is hidden
            const focusedElement = document.activeElement;
            if (focusedElement && modal.contains(focusedElement)) {
                focusedElement.blur();
            }
        });
        
        modalInstance.show();
    };
    
    function createMainGuestSelectorModal() {
        const modalHTML = `
            <div class="modal fade" id="mainGuestSelectorModal" tabindex="-1" aria-labelledby="mainGuestSelectorModalLabel">
                <div class="modal-dialog modal-lg">
                    <div class="modal-content">
                        <div class="modal-header bg-primary text-white">
                            <h5 class="modal-title" id="mainGuestSelectorModalLabel">
                                <i class="ri-group-line me-2"></i>Select Tour Guests
                            </h5>
                            <button type="button" class="btn-close btn-close-white" data-bs-dismiss="modal" aria-label="Close"></button>
                        </div>
                        <div class="modal-body">
                            <div class="row g-4">
                                <!-- Adults Section -->
                                <div class="col-md-6">
                                    <div class="card border-primary">
                                        <div class="card-header bg-primary text-white">
                                            <h6 class="mb-0"><i class="ri-user-line me-2"></i>Adults</h6>
                                        </div>
                                        <div class="card-body">
                                            <!-- Male -->
                                            <div class="guest-counter mb-3">
                                                <label class="form-label fw-semibold text-primary">
                                                    <i class="ri-user-3-line me-1"></i>Male
                                                </label>
                                                <div class="d-flex align-items-center">
                                                    <button type="button" class="btn btn-outline-primary btn-sm" onclick="updateMainGuest('male', -1)">
                                                        <i class="ri-subtract-line"></i>
                                                    </button>
                                                    <span class="mx-3 fw-bold fs-5" id="mainModalMale">0</span>
                                                    <button type="button" class="btn btn-outline-primary btn-sm" onclick="updateMainGuest('male', 1)">
                                                        <i class="ri-add-line"></i>
                                                    </button>
                                                </div>
                                            </div>
                                            <!-- Female -->
                                            <div class="guest-counter">
                                                <label class="form-label fw-semibold text-danger">
                                                    <i class="ri-user-4-line me-1"></i>Female
                                                </label>
                                                <div class="d-flex align-items-center">
                                                    <button type="button" class="btn btn-outline-danger btn-sm" onclick="updateMainGuest('female', -1)">
                                                        <i class="ri-subtract-line"></i>
                                                    </button>
                                                    <span class="mx-3 fw-bold fs-5" id="mainModalFemale">0</span>
                                                    <button type="button" class="btn btn-outline-danger btn-sm" onclick="updateMainGuest('female', 1)">
                                                        <i class="ri-add-line"></i>
                                                    </button>
                                                </div>
                                            </div>
                                        </div>
                                    </div>
                                </div>
                                
                                <!-- Children & Infants Section -->
                                <div class="col-md-6">
                                    <div class="card border-success">
                                        <div class="card-header bg-success text-white">
                                            <h6 class="mb-0"><i class="ri-user-smile-line me-2"></i>Children & Infants</h6>
                                        </div>
                                        <div class="card-body">
                                            <!-- Children -->
                                            <div class="guest-counter mb-3">
                                                <label class="form-label fw-semibold text-success">
                                                    <i class="ri-user-smile-line me-1"></i>Children
                                                    <small class="text-muted">(Ages 1-17)</small>
                                                </label>
                                                <div class="d-flex align-items-center">
                                                    <button type="button" class="btn btn-outline-success btn-sm" onclick="updateMainGuest('children', -1)">
                                                        <i class="ri-subtract-line"></i>
                                                    </button>
                                                    <span class="mx-3 fw-bold fs-5" id="mainModalChildren">0</span>
                                                    <button type="button" class="btn btn-outline-success btn-sm" onclick="updateMainGuest('children', 1)">
                                                        <i class="ri-add-line"></i>
                                                    </button>
                                                </div>
                                                <!-- Child Ages Section -->
                                                <div id="childAgesSection" class="mt-3" style="display: none;">
                                                    <label class="form-label fw-semibold text-success mb-2">
                                                        <i class="ri-user-settings-line me-1"></i>Select Ages for Children
                                                    </label>
                                                    <div id="childAgeDropdowns" class="d-flex flex-column gap-2">
                                                        <!-- Child age dropdowns will be added here dynamically -->
                                                    </div>
                                                </div>
                                            </div>
                                            <!-- Infants -->
                                            <div class="guest-counter">
                                                <label class="form-label fw-semibold text-warning">
                                                    <i class="ri-user-heart-line me-1"></i>Infants
                                                    <small class="text-muted">(Under 1 year)</small>
                                                </label>
                                                <div class="d-flex align-items-center">
                                                    <button type="button" class="btn btn-outline-warning btn-sm" onclick="updateMainGuest('infants', -1)">
                                                        <i class="ri-subtract-line"></i>
                                                    </button>
                                                    <span class="mx-3 fw-bold fs-5" id="mainModalInfants">0</span>
                                                    <button type="button" class="btn btn-outline-warning btn-sm" onclick="updateMainGuest('infants', 1)">
                                                        <i class="ri-add-line"></i>
                                                    </button>
                                                </div>
                                            </div>
                                        </div>
                                    </div>
                                </div>
                            </div>
                        </div>
                        <div class="modal-footer">
                            <button type="button" class="btn btn-outline-secondary" data-bs-dismiss="modal">Cancel</button>
                            <button type="button" class="btn btn-primary" onclick="applyMainGuestSelection()">
                                <i class="ri-check-line me-1"></i>Apply Selection
                            </button>
                        </div>
                    </div>
                </div>
            </div>
        `;
        
        document.body.insertAdjacentHTML('beforeend', modalHTML);
    }
    
    window.updateMainGuest = function(type, change) {
        const element = document.getElementById('mainModal' + type.charAt(0).toUpperCase() + type.slice(1));
        const currentValue = parseInt(element.textContent) || 0;
        let newValue = Math.max(0, currentValue + change);
        
        // For adults, ensure at least 1 adult is selected in total
        if ((type === 'male' || type === 'female') && change < 0) {
            const maleEl = document.getElementById('mainModalMale');
            const femaleEl = document.getElementById('mainModalFemale');
            const maleCount = maleEl ? parseInt(maleEl.textContent) || 0 : 0;
            const femaleCount = femaleEl ? parseInt(femaleEl.textContent) || 0 : 0;
            
            const totalAdults = (type === 'male' ? newValue : maleCount) + (type === 'female' ? newValue : femaleCount);
            
            if (totalAdults < 1) {
                return; // Don't allow reducing to 0 adults
            }
        }
        
        element.textContent = newValue;
        
        // Handle child age dropdowns
        if (type === 'children') {
            updateChildAgeDropdowns(newValue);
        }
    };
    
    // Function to create/update child age dropdowns
    function updateChildAgeDropdowns(childCount) {
        const childAgesSection = document.getElementById('childAgesSection');
        const childAgeDropdowns = document.getElementById('childAgeDropdowns');

        
        
        if (!childAgesSection || !childAgeDropdowns) return;
        
        // Show/hide the child ages section
        if (childCount > 0) {
            childAgesSection.style.display = 'block';
        } else {
            childAgesSection.style.display = 'none';
            childAgeDropdowns.innerHTML = '';
            return;
        }
        
        // Clear existing dropdowns
        childAgeDropdowns.innerHTML = '';
        
        // Get enquiry data and existing child ages
        const enquiry = @json($enquiry);
        console.log('Enquiry:', enquiry);
        
        let existingChildAges = [];
        if (enquiry && enquiry.child_ages) {
            if (typeof enquiry.child_ages === 'string') {
                // Handle comma-separated string format
                existingChildAges = enquiry.child_ages.split(',').map(age => parseInt(age.trim())).filter(age => !isNaN(age));
            } else if (Array.isArray(enquiry.child_ages)) {
                // Handle array format
                existingChildAges = enquiry.child_ages;
            }
        }
        console.log('Existing child ages:', existingChildAges);
        
        // Create dropdowns for each child
        for (let i = 1; i <= childCount; i++) {
            let ageOptions = '<option value="">Select age</option>';
            
            // Generate age options (1-17) with auto-selection
            for (let age = 1; age <= 17; age++) {
                const selected = existingChildAges[i-1] == age ? 'selected' : '';
                ageOptions += `<option value="${age}" ${selected}>${age} year${age > 1 ? 's' : ''}</option>`;
            }
            
            const dropdownHTML = `
                <div class="d-flex align-items-center mb-2">
                    <label class="me-2 text-success fw-semibold" style="min-width: 80px;">Child ${i}:</label>
                    <select class="form-select form-select-sm child-age-select" data-child-index="${i}">
                        ${ageOptions}
                    </select>
                </div>
            `;
            childAgeDropdowns.insertAdjacentHTML('beforeend', dropdownHTML);
        }
    }
    
    window.applyMainGuestSelection = function() {
        console.log('applyMainGuestSelection called');
        
        const male = parseInt(document.getElementById('mainModalMale').textContent) || 0;
        const female = parseInt(document.getElementById('mainModalFemale').textContent) || 0;
        const children = parseInt(document.getElementById('mainModalChildren').textContent) || 0;
        const infants = parseInt(document.getElementById('mainModalInfants').textContent) || 0;
        const adults = male + female;
        
        // Collect child ages
        const childAges = [];
        const childAgeSelects = document.querySelectorAll('.child-age-select');
        childAgeSelects.forEach(select => {
            if (select.value) {
                childAges.push(parseInt(select.value));
            }
        });
        
        console.log('Modal values:', {adults, male, female, children, infants, childAges});
        
        // Validate child ages if children are selected
        if (children > 0 && childAges.length !== children) {
            alert('Please select ages for all children before applying.');
            return;
        }
        
        // Update hidden inputs
        const adultsInput = document.getElementById('adults');
        const maleInput = document.getElementById('male');
        const femaleInput = document.getElementById('female');
        const childrenInput = document.getElementById('children');
        const infantsInput = document.getElementById('infants');
        const childAgesInput = document.getElementById('child_ages');
        
        if (adultsInput) adultsInput.value = adults;
        if (maleInput) maleInput.value = male;
        if (femaleInput) femaleInput.value = female;
        if (childrenInput) childrenInput.value = children;
        if (infantsInput) infantsInput.value = infants;
        if (childAgesInput) childAgesInput.value = JSON.stringify(childAges);
        
        // Update summary display with child ages
        const guestSummary = document.getElementById('mainGuestSummary');
        console.log('Guest summary element:', guestSummary);
        
        if (guestSummary) {
            let summaryText = `${adults} adults (${male} male, ${female} female), ${children} children`;
            if (children > 0 && childAges.length > 0) {
                summaryText += ` (ages: ${childAges.join(', ')})`;
            }
            summaryText += ` - ${infants} infants`;
            guestSummary.textContent = summaryText;
            console.log('Updated guest summary text');
        }
        
        // Update badges
        const badgeContainer = guestSummary.closest('.guest-display').querySelector('.guest-badges');
        if (badgeContainer) {
            const badges = badgeContainer.querySelectorAll('.badge');
            if (badges.length >= 3) {
                badges[0].textContent = adults; // Total adults
                badges[1].textContent = children; // Children
                badges[2].textContent = infants; // Infants
            }
        }
        
        // Refresh meal plans if a hotel is already selected
        const hotelSelect = document.getElementById('hotelSelect');
        if (hotelSelect && hotelSelect.value) {
            updateHotelDependentDropdowns(hotelSelect.value);
        }
        
        // Close modal
        const modal = bootstrap.Modal.getInstance(document.getElementById('mainGuestSelectorModal'));
        modal.hide();
        
        console.log('applyMainGuestSelection completed successfully');
    };

    // Ensure Bootstrap is properly loaded
    document.addEventListener('DOMContentLoaded', function() {
        // Check if Bootstrap is properly loaded
        if (typeof bootstrap === 'undefined') {
            console.error('Bootstrap JS is not loaded properly!');
        } else {
            console.log('Bootstrap version:', bootstrap.Modal.VERSION);
        }
        
        // Initialize transport service type styling
        if (typeof initializeTransportServiceTypeStyling === 'function') {
            initializeTransportServiceTypeStyling();
        }
    });
</script>

<script>
// Function to save customer information
function saveCustomerInfo() {
    const customerData = {
        fullName: document.getElementById('customerFullName').value,
        email: document.getElementById('customerEmail').value,
        phone: document.getElementById('customerPhone').value,
        countryCode: document.getElementById('customerCountryCode').value,
        address1: document.getElementById('customerAddress1').value,
        address2: document.getElementById('customerAddress2').value,
        state: document.getElementById('customerState').value,
        zip: document.getElementById('customerZip').value,
        specialRequests: document.getElementById('customerSpecialRequests').value
    };

    // Validate required fields
    const requiredFields = [''];
    const missingFields = requiredFields.filter(field => !customerData[field]);

    if (missingFields.length > 0) {
        alert('Please fill in all required fields: ' + missingFields.join(', '));
        return;
    }

    // Validate email format
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    if (!emailRegex.test(customerData.email)) {
        alert('Please enter a valid email address');
        return;
    }

    // Store the customer data in a hidden input for form submission
    const customerDataInput = document.getElementById('customerDataInput') || document.createElement('input');
    customerDataInput.type = 'hidden';
    customerDataInput.name = 'customer_data';
    customerDataInput.id = 'customerDataInput';
    customerDataInput.value = JSON.stringify(customerData);
    document.querySelector('form').appendChild(customerDataInput);

    // Show success message
    alert('Customer information saved successfully!');
}

// AJAX handler function
async function saveServiceOrder(type, data, agentId, tourId) {
    try {
        const response = await fetch('/api/save-service', {
            method: 'POST',
            headers: {
                'Content-Type': 'application/json',
                'X-CSRF-TOKEN': document.querySelector('meta[name="csrf-token"]').content
            },
            body: JSON.stringify({
                agent_id: agentId,
                tour_id: tourId,
                type: type,
                data: data
            })
        });

        const result = await response.json();
        if (!result.success) {
            throw new Error(result.message || 'Failed to save service');
        }
        return result;
    } catch (error) {
        console.error('Error saving service:', error);
        throw error;
    }
}

// Booking Data Management Functions
function addHotelBooking(hotelData) {
    const customerData = getCustomerData();
    const bookingData = {
        ...hotelData,
        ...customerData,
        bookingType: 'enquiry'
    };

    const bookings = JSON.parse(document.getElementById('hotelBookings').value || '[]');
    bookings.push(bookingData);
    document.getElementById('hotelBookings').value = JSON.stringify(bookings);
    updateBookingsSummary();
}

function addGuideBooking(guideData) {
    const customerData = getCustomerData();
    const bookingData = {
        ...guideData,
        ...customerData,
        bookingType: 'enquiry'
    };

    const bookings = JSON.parse(document.getElementById('guideBookings').value || '[]');
    bookings.push(bookingData);
    document.getElementById('guideBookings').value = JSON.stringify(bookings);
    updateBookingsSummary();
}

function addVehicleBooking(vehicleData) {
    const customerData = getCustomerData();
    const bookingData = {
        ...vehicleData,
        ...customerData,
        bookingType: 'enquiry'
    };

    const bookings = JSON.parse(document.getElementById('vehicleBookings').value || '[]');
    bookings.push(bookingData);
    document.getElementById('vehicleBookings').value = JSON.stringify(bookings);
    updateBookingsSummary();
}

function addAttractionBooking(attractionData) {
    const customerData = getCustomerData();
    const bookingData = {
        ...attractionData,
        ...customerData,
        bookingType: 'enquiry'
    };

    const bookings = JSON.parse(document.getElementById('attractionBookings').value || '[]');
    bookings.push(bookingData);
    document.getElementById('attractionBookings').value = JSON.stringify(bookings);
    updateBookingsSummary();
}

// Function to update bookings summary
function updateBookingsSummary() {
    const hotelBookings = JSON.parse(document.getElementById('hotelBookings').value || '[]');
    const guideBookings = JSON.parse(document.getElementById('guideBookings').value || '[]');
    const vehicleBookings = JSON.parse(document.getElementById('vehicleBookings').value || '[]');
    const attractionBookings = JSON.parse(document.getElementById('attractionBookings').value || '[]');

    const summary = [];
    if (hotelBookings.length > 0) summary.push(`${hotelBookings.length} Hotel(s)`);
    if (guideBookings.length > 0) summary.push(`${guideBookings.length} Guide(s)`);
    if (vehicleBookings.length > 0) summary.push(`${vehicleBookings.length} Vehicle(s)`);
    if (attractionBookings.length > 0) summary.push(`${attractionBookings.length} Attraction(s)`);

    document.getElementById('bookingsSummary').textContent = summary.length > 0 ? 
        summary.join(', ') : 'No bookings added yet';
}

// Helper function to get customer data
function getCustomerData() {
    return {
        fullName: document.getElementById('customerFullName').value,
        email: document.getElementById('customerEmail').value,
        phone: document.getElementById('customerPhone').value,
        countryCode: document.getElementById('customerCountryCode').value,
        address1: document.getElementById('customerAddress1').value,
        address2: document.getElementById('customerAddress2').value,
        state: document.getElementById('customerState').value,
        zip: document.getElementById('customerZip').value,
        specialRequests: document.getElementById('customerSpecialRequests').value
    };
}


// Function to validate service selections (time slots, meal types, etc.)
function validateServiceSelections() {
    let isValid = true;
    let errorMessages = [];
    
    // Validate attractions (time slots)
    const attractionSelects = document.querySelectorAll('.attraction-select');
    attractionSelects.forEach(select => {
        if (select.value) {
            // Get day and index from ID
            const idMatch = select.id.match(/day(\d+)_attraction_(\d+)/);
            if (idMatch) {
                const day = idMatch[1];
                const index = idMatch[2];
                
                // Check if time slot is selected
                const timeSelect = document.getElementById(`day${day}_attraction_${index}_time`);
                if (timeSelect && !timeSelect.value) {
                    const attractionName = select.options[select.selectedIndex].text;
                    errorMessages.push(`Day ${day}: Please select a time slot for ${attractionName}`);
                    isValid = false;
                    
                    // Highlight the missing field
                    timeSelect.classList.add('is-invalid');
                    timeSelect.addEventListener('change', function() {
                        this.classList.remove('is-invalid');
                    }, { once: true });
                }
            }
        }
    });
    
    // Validate guides (pickup time)
    const guideSelects = document.querySelectorAll('.guide-select');
    guideSelects.forEach(select => {
        if (select.value) {
            // Get day and index from ID
            const idMatch = select.id.match(/day(\d+)_guide_(\d+)/);
            if (idMatch) {
                const day = idMatch[1];
                const index = idMatch[2];
                
                // Check if pickup time is selected
                const pickupTimeInput = document.getElementById(`day${day}_guide_${index}_pickup_time`);
                if (pickupTimeInput && !pickupTimeInput.value) {
                    const guideName = select.options[select.selectedIndex].text;
                    errorMessages.push(`Day ${day}: Please select a pickup time for guide ${guideName}`);
                    isValid = false;
                    
                    // Highlight the missing field
                    const timeOptionsContainer = document.getElementById(`day${day}_guide_${index}_pickup_time_options`);
                    if (timeOptionsContainer) {
                        timeOptionsContainer.classList.add('border', 'border-danger');
                        timeOptionsContainer.addEventListener('click', function() {
                            this.classList.remove('border', 'border-danger');
                        }, { once: true });
                    }
                }
            }
        }
    });
    
    // Validate restaurants (meal type and dish)
    const restaurantSelects = document.querySelectorAll('.restaurant-select');
    restaurantSelects.forEach(select => {
        if (select.value) {
            // Get day and index from ID
            const idMatch = select.id.match(/day(\d+)_restaurant_(\d+)/);
            if (idMatch) {
                const day = idMatch[1];
                const index = idMatch[2];
                
                // Check if meal type is selected
                const mealTypeSelect = document.getElementById(`day${day}_meal_type_${index}`);
                if (mealTypeSelect && !mealTypeSelect.value) {
                    const restaurantName = select.options[select.selectedIndex].text;
                    errorMessages.push(`Day ${day}: Please select a meal type for ${restaurantName}`);
                    isValid = false;
                    
                    // Highlight the missing field
                    mealTypeSelect.classList.add('is-invalid');
                    mealTypeSelect.addEventListener('change', function() {
                        this.classList.remove('is-invalid');
                    }, { once: true });
                }
                
                // Check if dish is selected
                const dishSelect = document.getElementById(`day${day}_dish_${index}`);
                const dishContainer = document.getElementById(`day${day}_dish_container_${index}`);
                const mealIdField = document.getElementById(`day${day}_restaurant_${index}_meal_id`);
                
                // Check if any dish is selected (either via dropdown or buttons)
                if ((!dishSelect || !dishSelect.value) && (!mealIdField || !mealIdField.value)) {
                    const restaurantName = select.options[select.selectedIndex].text;
                    errorMessages.push(`Day ${day}: Please select a dish for ${restaurantName}`);
                    isValid = false;
                    
                    // Highlight the missing field
                    if (dishContainer && dishContainer.style.display !== 'none') {
                        dishContainer.classList.add('border', 'border-danger');
                        dishContainer.addEventListener('click', function() {
                            this.classList.remove('border', 'border-danger');
                        }, { once: true });
                    } else if (dishSelect) {
                        dishSelect.classList.add('is-invalid');
                        dishSelect.addEventListener('change', function() {
                            this.classList.remove('is-invalid');
                        }, { once: true });
                    }
                }
                
                // Check if time slot is selected
                const timeSlotSelect = document.getElementById(`day${day}_time_slot_${index}`);
                if (timeSlotSelect && !timeSlotSelect.value) {
                    const restaurantName = select.options[select.selectedIndex].text;
                    errorMessages.push(`Day ${day}: Please select a time slot for ${restaurantName}`);
                    isValid = false;
                    
                    // Highlight the missing field
                    timeSlotSelect.classList.add('is-invalid');
                    timeSlotSelect.addEventListener('change', function() {
                        this.classList.remove('is-invalid');
                    }, { once: true });
                }
            }
        }
    });
    
    // Show error messages if any
    if (!isValid) {
        // Create a nicely formatted alert
        const errorHTML = `
            <div class="alert alert-danger">
                <h5><i class="ri-error-warning-line me-2"></i>Please correct the following errors:</h5>
                <ul class="mb-0">
                    ${errorMessages.map(msg => `<li>${msg}</li>`).join('')}
                </ul>
            </div>
        `;
        
        // Show notification with the errors
        showNotification(errorHTML, 'error', 10000); // 10 second timeout for longer message
    }
    
    return isValid;
}

// Global variables (move outside DOMContentLoaded)
let tourStartDate = null;
let tourEndDate = null;
let selectedHotels = [];
let tourNights = 0;
let hotelData = [];

// Helper function to get tour date for a specific day
function getTourDateForDay(day) {
    if (!tourStartDate) {
        console.warn(`Tour start date not set, using today's date as fallback for day ${day}`);
        return new Date().toISOString().split('T')[0];
    }
    return moment(tourStartDate).add(day-1, 'days').format('YYYY-MM-DD');
}

document.addEventListener('DOMContentLoaded', function() {

    // Country and City Cascade (updated for section-specific city dropdowns)
    const userCountrySelect = document.getElementById('user_country');

    // Auto-load cities if country is pre-selected
    if (userCountrySelect.value) {
        userCountrySelect.dispatchEvent(new Event('change'));
    }

    userCountrySelect.addEventListener('change', function() {
        const selectedCountry = this.value;
        console.log('Country changed to:', selectedCountry);
        
        if (selectedCountry) {
            // Show loading state for all city dropdowns
            populateAllCityDropdowns(selectedCountry);
            
            // Also fetch ports for the selected country
            fetchPortsByCountry(selectedCountry);
            
            // Ensure all attraction city dropdowns are populated
            setTimeout(() => {
                const attractionCityDropdowns = document.querySelectorAll('.attraction-city-select');
                console.log(`Found ${attractionCityDropdowns.length} attraction city dropdowns to check`);
                
                attractionCityDropdowns.forEach(dropdown => {
                    if (dropdown.options.length <= 1) {
                        console.log(`Populating dropdown: ${dropdown.id}`);
                        populateCityDropdown(dropdown);
                    }
                });
            }, 1000);
        } else {
            // Clear all city dropdowns when no country is selected
            clearAllCityDropdowns();
            
            // Clear ports when no country is selected
            clearAllPortDropdowns();
        }
    });

    // Function to populate all city dropdowns based on selected country
    function populateAllCityDropdowns(selectedCountry) {
        console.log('Populating all city dropdowns for country:', selectedCountry);
        
        // Get all city dropdowns
        const cityDropdowns = [
            document.getElementById('hotelCitySelect'),
            ...document.querySelectorAll('.attraction-city-select'),
            ...document.querySelectorAll('.guide-city-select'), 
            ...document.querySelectorAll('.restaurant-city-select'),
            ...document.querySelectorAll('.transport-city-select')
        ].filter(dropdown => dropdown !== null);

        // Set loading state for all dropdowns
        cityDropdowns.forEach(dropdown => {
            dropdown.innerHTML = '<option value="">Loading cities...</option>';
            dropdown.disabled = true;
        });

        // Fetch cities from server
        setTimeout(function() {
            $.ajax({
                url: "{{ route('fetch-cities-by-country-single-tour') }}",
                type: "GET",
                data: { country: selectedCountry },
                dataType: 'json',
                success: function(response) {
                    console.log('Cities loaded for country:', selectedCountry, response);
                    
                    // Set country_id for the hidden field
                    const countryIdField = document.getElementById('country_id');
                    if (countryIdField) {
                        countryIdField.value = selectedCountry;
                    }
                    
                    // Populate all city dropdowns
                    cityDropdowns.forEach(dropdown => {
                        dropdown.innerHTML = '<option value="">Select city...</option>';
                        
                        if (response.cities && response.cities.length > 0) {
                            response.cities.forEach(function(city) {
                                dropdown.innerHTML += `<option value="${city.name}" data-id="${city.id}">${city.name}</option>`;
                            });
                        } else {
                            dropdown.innerHTML += '<option disabled>No cities found</option>';
                        }
                        
                        dropdown.disabled = false;
                    });
                },
                error: function(xhr, status, error) {
                    console.error('Error loading cities:', error);
                    cityDropdowns.forEach(dropdown => {
                        dropdown.innerHTML = '<option disabled>Error loading cities</option>';
                        dropdown.disabled = false;
                    });
                }
            });
        }, 300);
    }

    // Function to clear all city dropdowns
    function clearAllCityDropdowns() {
        const cityDropdowns = [
            document.getElementById('hotelCitySelect'),
            ...document.querySelectorAll('.attraction-city-select'),
            ...document.querySelectorAll('.guide-city-select'),
            ...document.querySelectorAll('.restaurant-city-select'),
            ...document.querySelectorAll('.transport-city-select')
        ].filter(dropdown => dropdown !== null);

        cityDropdowns.forEach(dropdown => {
            dropdown.innerHTML = '<option value="">Select country first</option>';
            dropdown.disabled = true;
        });
    }

    // Function to populate a single city dropdown based on selected country
    function populateCityDropdown(cityDropdown) {
        const userCountrySelect = document.getElementById('user_country');
        const selectedCountry = userCountrySelect ? userCountrySelect.value : '';
        
        if (!selectedCountry) {
            cityDropdown.innerHTML = '<option value="">Select country first</option>';
            cityDropdown.disabled = true;
            return;
        }
        
        // Set loading state
        cityDropdown.innerHTML = '<option value="">Loading cities...</option>';
        cityDropdown.disabled = true;
        
        // Fetch cities from server
        setTimeout(function() {
            $.ajax({
                url: "{{ route('fetch-cities-by-country-single-tour') }}",
                type: "GET",
                data: { country: selectedCountry },
                dataType: 'json',
                success: function(response) {
                    console.log('Cities loaded for dropdown:', response);
                    
                    cityDropdown.innerHTML = '<option value="">Select city...</option>';
                    
                    if (response.cities && response.cities.length > 0) {
                        response.cities.forEach(function(city) {
                            cityDropdown.innerHTML += `<option value="${city.name}" data-id="${city.id}">${city.name}</option>`;
                        });
                    } else {
                        cityDropdown.innerHTML += '<option disabled>No cities found</option>';
                    }
                    
                    cityDropdown.disabled = false;
                },
                error: function(xhr, status, error) {
                    console.error('Error loading cities for dropdown:', error);
                    cityDropdown.innerHTML = '<option disabled>Error loading cities</option>';
                    cityDropdown.disabled = false;
                }
            });
        }, 300);
    }



    // Hotel city selection handler
    document.addEventListener('change', function(e) {
        if (e.target.id === 'hotelCitySelect') {
            const selectedCity = e.target.value;
            const hotelSelect = document.getElementById('hotelSelect');
            const hotelLoadingStatus = document.getElementById('hotelLoadingStatus');
            const cityMessage = document.getElementById('hotelCityMessage');
            
            if (selectedCity) {
                // Enable hotel selection and load hotels
                hotelSelect.disabled = false;
                cityMessage.style.display = 'none';
                loadHotelsForCity(selectedCity);
            } else {
                // Disable hotel selection
                hotelSelect.disabled = true;
                hotelSelect.innerHTML = '<option value="">Select a city first to load hotels</option>';
                hotelLoadingStatus.innerHTML = '';
                cityMessage.style.display = 'block';
            }
        }
    });

    // Service city selection handlers for dynamically generated sections
    document.addEventListener('change', function(e) {
        // Handle attraction city selection
        if (e.target.classList.contains('attraction-city-select')) {
            const selectedCity = e.target.value;
            const selectId = e.target.id;
            const match = selectId.match(/day(\d+)_attraction_city_(\d+)/);
            if (match) {
                const day = match[1];
                const index = match[2];
                loadAttractionsForCity(day, selectedCity, index);
            }
        }
        
        // Handle guide city selection
        if (e.target.classList.contains('guide-city-select')) {
            const selectedCity = e.target.value;
            const selectId = e.target.id;
            const match = selectId.match(/day(\d+)_guide_city_(\d+)/);
            if (match) {
                const day = match[1];
                const index = match[2];
                loadGuidesForCity(day, selectedCity, index);
            }
        }
        
        // Handle restaurant city selection
        if (e.target.classList.contains('restaurant-city-select')) {
            const selectedCity = e.target.value;
            const selectId = e.target.id;
            const match = selectId.match(/day(\d+)_restaurant_city_(\d+)/);
            if (match) {
                const day = match[1];
                const index = match[2];
                loadRestaurantsForCity(day, selectedCity, index);
            }
        }
        
        // Handle transport city selection
        if (e.target.classList.contains('transport-city-select')) {
            const selectedCity = e.target.value;
            const selectId = e.target.id;
            const match = selectId.match(/day(\d+)_transport_city_(\d+)/);
            if (match) {
                const day = match[1];
                const index = match[2];
                loadTransportZonesForCity(day, selectedCity, index);
            }
        }
    });

    // Functions to load services based on city selection
    window.loadAttractionsForCity = function(day, cityName, index) {
        const attractionSelect = document.getElementById(`day${day}_attraction_${index}`);
        const cityMessage = document.getElementById(`day${day}_attraction_city_message_${index}`);
        
        if (cityName) {
            attractionSelect.disabled = false;
            attractionSelect.innerHTML = '<option value="">Loading attractions...</option>';
            cityMessage.style.display = 'none';
            
            // Load attractions for the specific city
            const currentDmcId = '{{ $finalDmcId }}';
            
            fetch(`{{ route('fetch-attractions-by-dmc') }}?city=${encodeURIComponent(cityName)}&dmc_id=${currentDmcId}`)
                .then(response => response.json())
                .then(data => {
                    attractionSelect.innerHTML = '<option value="">Search Attraction</option>';
                    
                    if (data.success && data.attractions) {
                        data.attractions.forEach(attraction => {
                            const option = document.createElement('option');
                            option.value = attraction.attraction_unique_id || attraction.id;
                            option.textContent = attraction.name;
                            option.dataset.city = attraction.city;
                            
                            // Set time slot data attributes for proper time slot generation
                            option.dataset.timeSlots = JSON.stringify(attraction.time_slots || []);
                            
                            // Extract first open and close time for time slot generation
                            let openTime = null;
                            let closeTime = null;
                            
                            if (attraction.time_slots && attraction.time_slots.length > 0) {
                                const firstSlot = attraction.time_slots[0];
                                if (firstSlot.open && firstSlot.close) {
                                    openTime = firstSlot.open;
                                    closeTime = firstSlot.close;
                                }
                            }
                            
                            option.dataset.openTime = openTime || '';
                            option.dataset.closeTime = closeTime || '';
                            
                            attractionSelect.appendChild(option);
                        });
                        console.log(`Loaded ${data.attractions.length} attractions for ${cityName}`);
                    } else {
                        attractionSelect.innerHTML += '<option disabled>No attractions found in this city</option>';
                    }
                    
                    attractionSelect.disabled = false;
                })
                .catch(error => {
                    console.error('Error loading attractions for city:', error);
                    attractionSelect.innerHTML = '<option disabled>Error loading attractions</option>';
                    attractionSelect.disabled = false;
                });
        } else {
            attractionSelect.disabled = true;
            attractionSelect.innerHTML = '<option value="">Select city first</option>';
            cityMessage.style.display = 'block';
        }
    }

    function loadGuidesForCity(day, cityName, index) {
        const guideSelect = document.getElementById(`day${day}_guide_${index}`);
        const cityMessage = document.getElementById(`day${day}_guide_city_message_${index}`);
        
        if (cityName) {
            guideSelect.disabled = false;
            guideSelect.innerHTML = '<option value="">Loading guides...</option>';
            cityMessage.style.display = 'none';
            
            // Load guides for the specific city
            const currentDmcId = '{{ $finalDmcId }}';
            
            fetch(`{{ route('fetch-guides-by-dmc') }}?city=${encodeURIComponent(cityName)}&dmc_id=${currentDmcId}`)
                .then(response => response.json())
                .then(data => {
                    guideSelect.innerHTML = '<option value="">Search Guide</option>';
                    
                    if (data.success && data.guides) {
                        data.guides.forEach(guide => {
                            const option = document.createElement('option');
                            option.value = guide.guide_id;
                            // Extract language names from the languages relationship
                            const languageNames = guide.languages ? guide.languages.map(lang => lang.language).join(', ') : 'Languages not specified';
                            option.textContent = `${guide.name} - ${languageNames}`;
                            option.dataset.city = guide.city;
                            
                            // Add pricing data attributes
                            option.dataset.nightStartTime = guide.night_start_time;
                            option.dataset.nightEndTime = guide.night_end_time;
                            option.dataset.dayRate = 0;
                            option.dataset.nightSurcharge = guide.night_surcharge;
                            option.dataset.hourlyPrice = guide.hourly_price;
                            option.dataset.twoHourPrice = guide.two_hour_price;
                            option.dataset.fourHourPrice = guide.four_hour_price;
                            option.dataset.sixHourPrice = guide.six_hour_price;
                            option.dataset.eightHourPrice = guide.eight_hour_price;
                            option.dataset.tenHourPrice = guide.ten_hour_price;
                            option.dataset.twelveHourPrice = guide.twelve_hour_price;
                            
                            guideSelect.appendChild(option);
                        });
                        console.log(`Loaded ${data.guides.length} guides for ${cityName}`);
                    } else {
                        guideSelect.innerHTML += '<option disabled>No guides found in this city</option>';
                    }
                    
                    guideSelect.disabled = false;
                })
                .catch(error => {
                    console.error('Error loading guides for city:', error);
                    guideSelect.innerHTML = '<option disabled>Error loading guides</option>';
                    guideSelect.disabled = false;
                });
        } else {
            guideSelect.disabled = true;
            guideSelect.innerHTML = '<option value="">Select city first</option>';
            cityMessage.style.display = 'block';
        }
    }

