                                                 <span>Total:</span>
                                                 <span>$${(() => {
                                                     const roomCost = (hotel.price || 0) * hotel.numberOfRooms * hotel.totalNights;
                                                     const mealCost = calculateCorrectMealCosts(hotel.mealPlan, hotel.totalNights, hotel.selectedPersons || 1, 0, hotel.mealPrices, hotel.numberOfRooms);
                                                     const extraBedCost = (hotel.extraBedPrice && hotel.extraBedPrice > 0 && hotel.selectedPersons > hotel.maxOccupancy) ? 
                                                         hotel.extraBedPrice * (hotel.selectedPersons - hotel.maxOccupancy) * hotel.numberOfRooms * hotel.totalNights : 0;
                                                     return roomCost + mealCost + extraBedCost;
                                                 })()}</span>
                                             </div>
                                         </div>
                                     </div>
                                 </div>
                             </div>
                         </div>
                     </div>
                 `;
             });
             container.innerHTML = hotelsHtml;
         }
         
         // Update summary
         document.getElementById('totalHotels').textContent = selectedHotels.length;
         const totalNights = selectedHotels.reduce((sum, hotel) => sum + hotel.totalNights, 0);
         document.getElementById('totalNights').textContent = totalNights + ' Nights';
    }

         // Generate daily services based on tour dates
    function generateDailyServices() {
         const container = document.getElementById('dailyServicesContainer');
         
         // Ensure we have valid tour dates
         if (!tourStartDate || !tourEndDate) {
             console.log('Tour dates not set, cannot generate daily services');
             return;
         }
         
         console.log('Generating daily services for tour');
         
         const totalDays = moment(tourEndDate).diff(moment(tourStartDate), 'days') + 1;
         
         // Update day count
         document.getElementById('transportDayCount').textContent = totalDays + ' Days';
         
         let servicesHTML = '';
         
        // Only show Day 1 and last day with exit port (if more than 1 day)
        const daysToShow = totalDays > 1 ? [1, totalDays] : [1];
        
        for (let dayIndex = 0; dayIndex < daysToShow.length; dayIndex++) {
            const day = daysToShow[dayIndex];
            const currentDate = moment(tourStartDate).add(day-1, 'days');
            const isFirstDay = day === 1;
            const isLastDay = day === totalDays;
             
                         servicesHTML += `
                <div class="daily-service-section border-bottom" id="day${day}">
                    <div class="day-header p-3 bg-gradient-primary text-white">
                         <div class="d-flex justify-content-between align-items-center">
